package org.sleepwell.app;
import java.util.concurrent.atomic.*;import org.junit.Test;import static org.junit.Assert.*;
public final class ArmedWaitTest {
    @Test public void defaultConditionsKeepEveryExistingAdmissionUnchanged(){ArmedWaitConditions none=ArmedWaitConditions.NONE;assertEquals("",none.blocked(false,true));int[] starts={0};AutomaticTransition transition=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->starts[0]++);assertEquals(AutomaticSleep.State.START,transition.tick(1000,true));assertEquals(1,starts[0]);}
    @Test public void selectedConditionsBlockIndependentlyAndInStableOrder(){assertEquals("WAITING_CHARGING",new ArmedWaitConditions(true,false).blocked(false,false));assertEquals("",new ArmedWaitConditions(true,false).blocked(true,true));assertEquals("WAITING_SCREEN_OFF",new ArmedWaitConditions(false,true).blocked(false,true));ArmedWaitConditions both=new ArmedWaitConditions(true,true);assertEquals("WAITING_CHARGING",both.blocked(false,true));assertEquals("WAITING_SCREEN_OFF",both.blocked(true,true));assertEquals("",both.blocked(true,false));}
    @Test public void timedWaitHoldsPastScheduledTimeThenStartsOnceWhenEligible(){AtomicBoolean allowed=new AtomicBoolean(false);int[] starts={0};AutomaticTransition transition=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->starts[0]++,allowed::get);assertEquals(AutomaticSleep.State.WAITING,transition.tick(1000,true));transition.sample(2000,.01,false);assertEquals(0,starts[0]);allowed.set(true);assertEquals(AutomaticSleep.State.START,transition.tick(3000,false));transition.tick(4000,false);assertEquals(1,starts[0]);}
    @Test public void blockedStillnessNeverAccumulatesEvidenceAndEligibilityStartsNewWindow(){AtomicBoolean allowed=new AtomicBoolean(false);int[] starts={0};AutomaticSleep evidence=new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0);AutomaticTransition transition=new AutomaticTransition(evidence,()->starts[0]++,allowed::get);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)transition.sample(at,.01,false);assertEquals(0,evidence.quietMillis(AutomaticSleep.QUIET_REQUIRED));allowed.set(true);long first=AutomaticSleep.QUIET_REQUIRED+200;transition.sample(first,.01,false);assertFalse(transition.tick(first,false)==AutomaticSleep.State.START);for(long at=first+200;at<=first+AutomaticSleep.QUIET_REQUIRED;at+=200)transition.sample(at,.01,false);transition.tick(first+AutomaticSleep.QUIET_REQUIRED,false);assertEquals(1,starts[0]);}
    @Test public void conditionLostAfterQualifyingSampleRevokesPendingStart(){AtomicBoolean allowed=new AtomicBoolean(true);int[] starts={0};AutomaticSleep evidence=new AutomaticSleep(AutomaticSleep.Mode.STILLNESS,0,0);AutomaticTransition transition=new AutomaticTransition(evidence,()->starts[0]++,allowed::get);for(long at=0;at<=AutomaticSleep.QUIET_REQUIRED;at+=200)transition.sample(at,.01,false);assertEquals(AutomaticSleep.State.START,evidence.state());allowed.set(false);assertEquals(AutomaticSleep.State.WAITING,transition.tick(AutomaticSleep.QUIET_REQUIRED+1,false));assertEquals(0,starts[0]);allowed.set(true);assertEquals(AutomaticSleep.State.COLLECTING,transition.tick(AutomaticSleep.QUIET_REQUIRED+3000,false));}
    @Test public void finalConditionRecheckCanRevokeTimedStartWithoutClosingWait(){AtomicInteger reads=new AtomicInteger();int[] starts={0};AutomaticTransition transition=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.SMART_WINDOW,0,1000),()->starts[0]++,()->reads.incrementAndGet()!=2);assertEquals(AutomaticSleep.State.WAITING,transition.tick(1000,false));assertEquals(0,starts[0]);transition.tick(2000,false);assertEquals(1,starts[0]);}
    @Test public void conditionsDoNotExtendDeadlineOrCreateSessionAfterCancel(){AtomicBoolean allowed=new AtomicBoolean(false);int[] starts={0};AutomaticTransition expired=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->starts[0]++,allowed::get);assertEquals(AutomaticSleep.State.EXPIRED,expired.tick(AutomaticSleep.MAX_WAIT,false));allowed.set(true);expired.tick(AutomaticSleep.MAX_WAIT+1,false);assertEquals(0,starts[0]);AutomaticTransition cancelled=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->starts[0]++,allowed::get);cancelled.cancel();cancelled.tick(2000,false);assertEquals(0,starts[0]);}
    @Test public void frozenPolicyDoesNotStopAlreadyStartedCaptureOrRetryFailedStart(){AtomicBoolean allowed=new AtomicBoolean(true);int[] starts={0};AutomaticTransition transition=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->starts[0]++,allowed::get);transition.tick(1000,false);allowed.set(false);transition.tick(2000,true);assertEquals(1,starts[0]);AutomaticTransition failed=new AutomaticTransition(new AutomaticSleep(AutomaticSleep.Mode.BEDTIME,0,1000),()->{starts[0]++;throw new IllegalStateException("Store unavailable");},()->true);assertThrows(IllegalStateException.class,()->failed.tick(1000,false));failed.tick(2000,false);assertEquals(2,starts[0]);}
}
